        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF25101.chb_Emp_onclick" });
    }
};

/**
 * @method
 * @name chb_Fmm_onclick
 * @description chb_Fmm 클릭 이벤트
 * @returns {void}
