        $c.exception.handleError(ex, { context : "ULDSTF25101.chb_Fmm_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description 공시일자, 팀, 담당자 세팅
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    scwin.gDepCd = js_dep_cd;
    scwin.gEmpNo = js_emp_no;

    //  기간 from~ to  셋팅(공시일자)
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_SDATE.setValue($c.ut.cGetMinusYear(vCurDate, 1)); // 1년전 날짜
    edt_EDATE.setValue(vCurDate); // 현재날짜

    // 팀 리스트 박스(소속부서와 같은 상위부서인 팀)
    const sbmOptions = {
        id : "sbm_dts_dep",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_dep=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    // 담당자 리스트 박스(소속부서와 같은 상위부서인 팀원)
    const sbmOptions2 = {
        id : "sbm_dts_emp",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_emp=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name search
 * @description 조회 버튼
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    scwin.colorCnt = 1; // 조회를 클릭한 경우에만 컬럼 color 변경해줌

    const flag = rdo_MKT_ID.getValue();
    if (flag === "") {
        await $c.win.alert("[시장구분]을 선택하세요.");
        rdo_MKT_ID.focus();
        return;
    } else {
        scwin.gDepCd = cmb_TeamList.getValue();
        scwin.gEmpNo = cmb_EmpList.getValue();
        if (scwin.gEmpNo === "") {
            scwin.gEmpNo = '%';
        }
        if (scwin.gDepCd === "") {
            scwin.gDepCd = 'all';
        }
    }
    url += "&MKT_ID=" + rdo_MKT_ID.getValue(); // 시장구분
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue(); // 법인코드
    url += "&LIST_STAT_CD=" + chb_TAB1_LIST_STAT_CD.getValue(); // 상장폐지법인 제외
    url += "&SDATE=" + edt_SDATE.getValue(); // 공시일자 from
    url += "&EDATE=" + edt_EDATE.getValue(); // 공시일자 to
    url += "&DEP_CD=" + scwin.gDepCd; // 팀			->수정
    url += "&EMP_NO=" + scwin.gEmpNo; // 담당자	->수정
    url += "&UP_DEP_CD=" + js_belngdepcd; //->수정
    url += "&ACNTCLS_MMDD1=" + cmb_f_mm_1.getValue(); // 결산월
    url += "&SCREN_ID=" + 'ULDSTF25101.xml';
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&TEAM_YN=" + scwin.getChkValue(chb_Team);
    url += "&EMP_YN=" + scwin.getChkValue(chb_Emp);
    url += "&FMM_YN=" + scwin.getChkValue(chb_Fmm);
    url += "&IND_YN=" + scwin.getChkValue(chb_Ind);
    url += "&BIG_YN=" + scwin.getChkValue(chb_BigYN);
    url += "&URL_YN=" + scwin.getChkValue(chb_URL);
    const sbmOptions = {
        id : "sbm_dts_Grid",
        action : "/InvestStatistics.do",
        ref : "",
        target : "dts_Grid=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getProvider
 * @description get Provider 처리
 * @returns {void}
 * @hidden N
 */
scwin.getProvider = function() {
    let url = frame.srcUrl;
    const arr = url.split("?");
    return (arr.length >= 1 ? arr[1] : "");
};

/**
 * @method
 * @name getParentValue
 * @description get Parent Value 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.getParentValue = async function() {
    const pvd = scwin.getProvider();
    if (pvd !== null) {
        const Temp0 = pvd.split("&")[0];
        const Temp1 = pvd.split("&")[1];
        const Temp2 = pvd.split("&")[2];
        const gIsurCd = Temp0.split("=")[1];
        if ($c.ut.trim(gIsurCd).length === 5) {
            txb_ISUR_CD.setValue(gIsurCd);
        }
        const gMktCd = Temp1.split("=")[1];
        scwin.gLdMktTp = gMktCd;
        const gComNm = Temp2.split("=")[1];
        txb_COM_NM.setValue(gComNm);
        scwin.init();
        await scwin.search();
    }
};

/**
 * @method
 * @name setContnId
 * @description 그리드에서 클릭 row의 변수셋팅
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.setContnId = function(obj) {
    scwin.gAcptNo = dts_Grid.getCellData(Number(obj), "ACPT_NO");
};

/**
 * @method
 * @name addDsclTeamAll
 * @description 공시팀 전체 목록에 추가
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.addDsclTeamAll = function(rowcount) {
    dts_dep.setCellData(2, "VALUE", 'UPTEAM'); //
    dts_dep.setCellData(2, "TEXT", '공시팀 전체');
    dts_dep.setCellData(2, "DEP_CD", 'UPTEAM');
    dts_dep.setBroadcast(false);
    for (let i = 3; i <= rowcount; i++) {
        dts_dep.setCellData(i, "VALUE", dts_dep1.getCellData(i - 1, "VALUE")); //
        dts_dep.setCellData(i, "TEXT", dts_dep1.getCellData(i - 1, "TEXT"));
        dts_dep.setCellData(i, "DEP_CD", dts_dep1.getCellData(i - 1, "DEP_CD"));
    }
    dts_dep.setBroadcast(true, true);
    dts_dep.insertRow();
    dts_dep.setCellData(rowcount + 1, "VALUE", dts_dep1.getCellData(rowcount, "VALUE")); //
    dts_dep.setCellData(rowcount + 1, "TEXT", dts_dep1.getCellData(rowcount, "TEXT"));
    dts_dep.setCellData(rowcount + 1, "DEP_CD", dts_dep1.getCellData(rowcount, "DEP_CD"));
};

/**
 * @method
 * @name getChkValue
 * @description get Chk Value 처리
 * @param {Object} obj 컴포넌트
 * @returns {void}
 * @hidden N
 */
scwin.getChkValue = function(obj) {
    return (obj.checked) ? "Y" : "N";
};

/**
 * @method
 * @name setGridHiddenColumnProp
 * @description set Grid Hidden Column Prop 처리
 * @returns {void}
 * @hidden N
 */
scwin.setGridHiddenColumnProp = function() {
    if (chb_Team.checked === true) {
        // 담당팀
        $c.cm.setColumnProp(grd_Grid, "DEP_NM", 'Show', true);
    } else {
        $c.cm.setColumnProp(grd_Grid, "DEP_NM", 'Show', false);
    }
    if (chb_Emp.checked === true) {
        // 담당자
        $c.cm.setColumnProp(grd_Grid, "EMP_NM", 'Show', true);
    } else {
        $c.cm.setColumnProp(grd_Grid, "EMP_NM", 'Show', false);
    }
    if (chb_Fmm.checked === true) {
        // 결산월
        $c.cm.setColumnProp(grd_Grid, "ACNTCLS_MMDD1", 'Show', true);
    } else {
        $c.cm.setColumnProp(grd_Grid, "ACNTCLS_MMDD1", 'Show', false);
    }
    if (chb_Ind.checked === true) {
        // 업종
        $c.cm.setColumnProp(grd_Grid, "STD_IND_NM", 'Show', true);
    } else {
        $c.cm.setColumnProp(grd_Grid, "STD_IND_NM", 'Show', false);
    }
    if (chb_BigYN.checked === true) {
        // 대규모법인여부
        $c.cm.setColumnProp(grd_Grid, "BIG_YN", 'Show', true);
    } else {
        $c.cm.setColumnProp(grd_Grid, "BIG_YN", 'Show', false);
    }
};
